{"cmd": "$enc=New-Object System.Text.UTF8Encoding($false)
$base='src\main\java\com\example\starter'
New-Item -ItemType Directory -Force -Path "$base\config","$base\model","$base\repo","$base\service","$base\web" | Out-Null
[System.IO.File]::WriteAllText("$base\config\TimeConfig.java",@'
package com.example.starter.config;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：业务统一使用 UTC 时钟，测试可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    /**
     * 系统 UTC 时钟。
     */
    @Bean
    public Clock businessClock() {
        return Clock.systemUTC();
    }
}
'@,$enc)
[System.IO.File]::WriteAllText("$base\model\AllocationStatus.java",@'
package com.example.starter.model;

/**
 * 接收时隙分配状态。
 */
public enum AllocationStatus {
    /** 已确认，占用天线时隙。 */
    CONFIRMED,
    /** 预测修订后不再满足新窗口，待重新分配，不占用天线。 */
    PENDING_REASSIGN,
    /** 接收完成，已记录实际字节数（终态）。 */
    COMPLETED,
    /** 已取消，释放天线时隙（终态）。 */
    CANCELLED
}
'@,$enc)
[System.IO.File]::WriteAllText("$base\model\RejectReason.java",@'
package com.example.starter.model;

/**
 * 业务拒绝原因码，随 409 响应返回，便于调用方区分。
 */
public enum RejectReason {
    /** 请求时隙超出预测可见窗口，存在窗口缺口。 */
    WINDOW_GAP,
    /** 时隙时长乘以容量快照不足以容纳计划数据量。 */
    CAPACITY_EXCEEDED,
    /** 预测最低仰角未达到站点门槛。 */
    ELEVATION_BELOW_THRESHOLD,
    /** 同一天线在该时段已存在已确认时隙。 */
    ANTENNA_OVERLAP,
    /** 同一 requestId 携带了不同参数。 */
    IDEMPOTENCY_CONFLICT,
    /** 请求基于已被修订取代的预测版本。 */
    STALE_PREDICTION,
    /** 当前状态不允许该操作（如已完成又取消）。 */
    INVALID_STATE,
    /** 实际字节数超过计划数据量。 */
    ACTUAL_BYTES_EXCEED_PLANNED,
    /** 引用的资源不存在。 */
    NOT_FOUND
}
'@,$enc)"}

